class Solution {
    public int rob(int[] nums) {
        int n = nums.length;
        if(n == 1) return nums[0];
        return Math.max(f(nums,0,n-2), f(nums,1,n-1));
    }
    private int f(int[] nums, int left, int right){
        int length = right-left+1;
        if(length == 1) return nums[left];
        if(length == 2) return Math.max(nums[left],nums[right]);
        int[] dp = new int[length];
        dp[0] = nums[left];
        dp[1] = Math.max(nums[left],nums[left+1]);
        for(int i=2;i<length;i++){
            dp[i] = Math.max(dp[i-1], dp[i-2]+nums[left+i]);
        }
        return dp[length-1];
    }
}
